
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_bloc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_bloc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.718578721455931e+00, -4.623231185935976e+00, -4.489604750892644e+00, -4.304460281206716e+00, -4.052119064330845e+00, -3.716235168037184e+00, -3.284183752286068e+00, -2.755733316667778e+00, -2.158042373585751e+00, -1.562095225053178e+00, -1.027670704871287e+00, -6.917054536468441e-01, -5.991371813577492e-01, -5.091327950544949e-01, -3.684207083618428e-01, -2.322390565120313e-01, -1.313790338013203e-01, -4.950391747929849e-02, -1.081191816558354e-02, -1.216202148314421e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


